struct T_LLAN_BASE
{
	T_ELEM_K KeyElem;
	double Eccentricity;
	double fact;
	BOOL   bSpanStart;
	double dEccenVertLoad;
	double dCentF;

	void Initialize()
	{
		KeyElem=0;
		Eccentricity=0;
		fact=0;
		bSpanStart = FALSE;
		dEccenVertLoad = 0.0;
		dCentF = 0.5;
	}
	void Convert895(T_LLAN_BASE_895& rData)
	{
		KeyElem = rData.KeyElem;
		Eccentricity = rData.Eccentricity;
		fact = rData.fact;
		bSpanStart = rData.bSpanStart;
		dEccenVertLoad = rData.dEccenVertLoad;
		dCentF = 0.5;
	}
	void Convert821(T_LLAN_BASE_821& rData)
	{
		KeyElem = rData.KeyElem;
		Eccentricity = rData.Eccentricity;
		fact = rData.fact;
		bSpanStart = rData.bSpanStart;
		dEccenVertLoad = 0.0;
		dCentF = 0.5;
	}
	void Convert590(T_LLAN_BASE_590& rData)
	{
		KeyElem = rData.KeyElem;
		Eccentricity = rData.Eccentricity;
		fact = rData.fact;
		bSpanStart = FALSE;
		dEccenVertLoad = 0.0;
		dCentF = 0.5;
	}
};
#define T_LLAN_DT CArray<T_LLAN_BASE, T_LLAN_BASE&>
