struct T_LLAN_D
{
	CString LineLaneName;
	T_LLAN_DT arLaneData;
	unsigned int LineLaneId;
	int nLoadDistribution;    // 1:Lane Element, 2:Cross Beam
	T_GRUP_K  ElemGroup;      // if nLoadDistribution=2
	double    dSkewStart;
	double    dSkewEnd;
	int       nMovingDir;     // 0:Forward, 1:Backward, 2:Both
	double    dLineWidth;     // 6.9.1에서 추가 (BS BD 37/01에서 사용)
	double    dWheelSpace;    // 7.1.0에서 추가
	//double    dScaleFactor;   // 7.2.0에서 추가 // v720 ScaleFactor 추가하려 했으나 보류되었음
	BOOL      bAutoOptimize;  // 8.4.0에서 추가 // 횡방향 이동하중 자동 탐색 옵션 (방법1) (참고: 방법 2는 T_LLANop_D 를 씀)
	double    dAllowWidth;
	int       nLaneType;      // BS : 0:Roadway, 1:Railway

	void Initialize()
	{
		LineLaneName.Empty();
		arLaneData.RemoveAll();
		LineLaneId = 0;
		nLoadDistribution = 1;
		ElemGroup = 0;
		dSkewStart = 0.0;
		dSkewEnd = 0.0;
		nMovingDir = 2;
		dLineWidth = 3.0;
		dWheelSpace = 0.0;  // 대화상자에서 국가별로 초기화
		//dScaleFactor = 1.0;
		bAutoOptimize = FALSE;
		dAllowWidth = 0.0;
		nLaneType = 0;
	}
	T_LLAN_D()
	{
	}
	T_LLAN_D(T_LLAN_D& src)
	{
		*this = src;
	}
	T_LLAN_D& operator=(T_LLAN_D& src)
	{
		LineLaneName=src.LineLaneName;
		arLaneData.Copy(src.arLaneData);
		LineLaneId = src.LineLaneId;
		nLoadDistribution = src.nLoadDistribution;
		ElemGroup = src.ElemGroup;
		dSkewStart = src.dSkewStart;
		dSkewEnd = src.dSkewEnd;
		nMovingDir = src.nMovingDir;
		dLineWidth = src.dLineWidth;
		dWheelSpace = src.dWheelSpace;
		//dScaleFactor = src.dScaleFactor;
		bAutoOptimize = src.bAutoOptimize;
		dAllowWidth = src.dAllowWidth;
		nLaneType = src.nLaneType;
		return *this;
	}
};
struct T_LLAN_D_CH
{
	char LineLaneName[40];
	T_LLAN_DT arLaneData;
	unsigned int LineLaneId;
	int nLoadDistribution;
	T_GRUP_K ElemGroup;
	double dSkewStart;
	double dSkewEnd;
	int    nMovingDir;
	double dLineWidth;
	double dWheelSpace;
	//double dScaleFactor; // v720 ScaleFactor 추가하려 했으나 보류되었음
	BOOL bAutoOptimize; 
	double dAllowWidth;
	int  nLaneType;      // BS : 0:Roadway, 1:Railway

	void ConvertToString(T_LLAN_D& rData)
	{
		ConvertCharStr(LineLaneName, rData.LineLaneName, sizeof(LineLaneName));
		rData.arLaneData.Copy(arLaneData);
		rData.LineLaneId=LineLaneId;
		rData.nLoadDistribution = nLoadDistribution;
		rData.ElemGroup = ElemGroup;
		rData.dSkewStart = dSkewStart;
		rData.dSkewEnd = dSkewEnd;
		rData.nMovingDir = nMovingDir;
		rData.dLineWidth = dLineWidth;
		rData.dWheelSpace = dWheelSpace;
		//rData.dScaleFactor = dScaleFactor;
		rData.bAutoOptimize = bAutoOptimize;
		rData.dAllowWidth = dAllowWidth;
		rData.nLaneType = nLaneType;
	}
	void ConvertToChar(T_LLAN_D& rData)
	{
		ConvertStrChar(rData.LineLaneName, LineLaneName, sizeof(LineLaneName));
		arLaneData.Copy(rData.arLaneData);
		LineLaneId=rData.LineLaneId;
		nLoadDistribution = rData.nLoadDistribution;
		ElemGroup = rData.ElemGroup;
		dSkewStart = rData.dSkewStart;
		dSkewEnd = rData.dSkewEnd;
		nMovingDir = rData.nMovingDir;
		dLineWidth = rData.dLineWidth;
		dWheelSpace = rData.dWheelSpace;
		//dScaleFactor = rData.dScaleFactor;
		bAutoOptimize = rData.bAutoOptimize;
		dAllowWidth = rData.dAllowWidth;
		nLaneType = rData.nLaneType;
	}
};
