struct T_SLANop_D
{
	CString LaneName;
	T_SLANop_DT arLaneData;
	unsigned int LaneId;
	double dSkewStart;
	double dSkewEnd;
	int    nMovingDir;       // 0:Forward, 1:Backward, 2:Both
	double dOptimWidth;
	double dLaneWidth;
	double dAnalLaneOffset;
	double dWheelSpace;
	double dMargin;
	BOOL   bStradd;        // EuroCode, BS Straddling Lane 일때 사용
	int    nOffsetType;    // 0: nDivideNum 사용  1: dAnalLaneOffset 사용    
	int    nDivideNum;
	int    nLaneType;      // BS : 0:Roadway, 1:Railway

	void Initialize()
	{
		LaneName.Empty();
		arLaneData.RemoveAll();
		LaneId=0;
		dSkewStart = 0.0;
		dSkewEnd = 0.0;
		nMovingDir = 2;
		dOptimWidth = 0.0;
		dLaneWidth = 0.0;
		dAnalLaneOffset = 0.0;
		dWheelSpace = 0.0;
		dMargin = 0.0;
		bStradd = FALSE;
		nOffsetType = 0;
		nDivideNum = 1;
		nLaneType = 0;
	}
	T_SLANop_D() {}
	T_SLANop_D(T_SLANop_D& src) { *this = src; }
	T_SLANop_D& operator=(T_SLANop_D& src)
	{
		LaneName = src.LaneName;
		arLaneData.Copy(src.arLaneData);
		LaneId =src.LaneId;
		dSkewStart = src.dSkewStart;
		dSkewEnd = src.dSkewEnd;
		nMovingDir = src.nMovingDir;
		dOptimWidth = src.dOptimWidth;
		dLaneWidth = src.dLaneWidth;
		dAnalLaneOffset = src.dAnalLaneOffset;
		dWheelSpace = src.dWheelSpace;
		dMargin = src.dMargin;
		bStradd = src.bStradd;
		nOffsetType = src.nOffsetType;
		nDivideNum = src.nDivideNum;
		nLaneType = src.nLaneType;

		return *this;
	}
};

