struct T_MVHL_PERMIT_LOAD // 7.0.2부터 추가
{
	double dImpactFactor; // 7.5.0
	int nVS_Idx;          // 7.5.0 - 0: 없음 1 부터 시작
	CArray<T_MVHL_AXLE_TYPE, T_MVHL_AXLE_TYPE&> aAxleType;
	CArray<T_MVHL_PERMIT_ITEM, T_MVHL_PERMIT_ITEM&> aPermitLoad;
	T_MVHL_PERMIT_LOAD() {}
	T_MVHL_PERMIT_LOAD(const T_MVHL_PERMIT_LOAD& crData) { *this = crData; }
	T_MVHL_PERMIT_LOAD& operator=(const T_MVHL_PERMIT_LOAD& crData)
	{
		dImpactFactor = crData.dImpactFactor;
		nVS_Idx = crData.nVS_Idx;
		aAxleType.Copy(crData.aAxleType);
		aPermitLoad.Copy(crData.aPermitLoad);

		return *this;
	}
	void Initialize()
	{
		dImpactFactor = 0.;
		nVS_Idx = 0;
		aAxleType.RemoveAll();
		aPermitLoad.RemoveAll();
	}
};

struct T_MVHL_PERMIT_LOAD_FXD
{
	double dImpactFactor; // 7.5.0
	int nVS_Idx;          // 7.5.0 - 0: 없음 1 부터 시작
	CArray<int, int> aAxleType;
	CArray<T_MVHL_PERMIT_ITEM, T_MVHL_PERMIT_ITEM&> aPermitLoad;

	void Set(T_MVHL_PERMIT_LOAD& rData, CMap<int, int, T_MVHL_AXLE_TYPE, T_MVHL_AXLE_TYPE&>& rmAxleType)
	{
		dImpactFactor = rData.dImpactFactor;
		nVS_Idx = rData.nVS_Idx;
		int nAxleTypeKey = (int)rmAxleType.GetCount();
		aAxleType.SetSize(rData.aAxleType.GetSize());
		for (int i = 0; i < rData.aAxleType.GetSize(); i++)
		{
			nAxleTypeKey++;
			aAxleType[i] = nAxleTypeKey;
			rmAxleType.SetAt(nAxleTypeKey, rData.aAxleType[i]);
		}
		aPermitLoad.Copy(rData.aPermitLoad);
	}
	void Get(T_MVHL_PERMIT_LOAD& rData, CMap<int, int, T_MVHL_AXLE_TYPE, T_MVHL_AXLE_TYPE&>& rmAxleType)
	{
		rData.dImpactFactor = dImpactFactor;
		rData.nVS_Idx = nVS_Idx;
		rData.aAxleType.SetSize(aAxleType.GetSize());
		for (int i = 0;i < aAxleType.GetSize(); i++)
		{
			rmAxleType.Lookup(aAxleType[i], rData.aAxleType[i]);
		}
		rData.aPermitLoad.Copy(aPermitLoad);
	}
};

