	// MNET1244, KJH20050312
	static void ConvQCUserTrain(double& dFD, double& dBD, double& dDD, 
															double dPointLoad2[], double dPointDistance2[],
															BOOL bStandard, int nLoadType, int nTrainType,
															double dPointLoad[], double dPointDistance[], double dD1)
	{
		BOOL bFind = FALSE;
		int nIndex = 0;
		for(int i=0; i<D_MVHL_NUMLOAD; i++)
		{
			dPointLoad2[i] = dPointDistance2[i] = 0.0;
			if(dPointLoad[i]==0.0 && !bFind) { bFind = TRUE; nIndex = i; }
		}
		if(bStandard || nLoadType!=1 || nTrainType!=2) // user, train, 중국 type2 일때만 변환
		{
			dFD = dBD = dDD = 0.0;
			return;
		}
		dDD = dD1;
		if(nIndex==8) // QC-10, QC-15
		{
			dFD = dPointDistance[1], dBD = dPointDistance[3]; // D2->FD, D4->BD
			dPointLoad2[0] = dPointLoad[2], dPointLoad2[1] = dPointLoad[3]; // P3~P4
			dPointDistance2[0] = dPointDistance[2]; // D3
			nIndex = 1;
		}
		else if(nIndex==9) // QC-20
		{
			dFD = dPointDistance[1], dBD = dPointDistance[4]; // D2->FD, D5->BC
			dPointLoad2[0] = dPointLoad[2], dPointLoad2[1] = dPointLoad[3], dPointLoad2[2] = dPointLoad[4]; // P3~P5
			dPointDistance2[0] = dPointDistance[2], dPointDistance2[1] = dPointDistance[3]; // D3~D4
			nIndex = 1;
		}
		else if(nIndex==13) // QC-C20
		{
			dFD = dPointDistance[3], dBD = dPointDistance[8]; // D4->FD, D9->BD
			dPointLoad2[0] = dPointLoad[4], dPointLoad2[1] = dPointLoad[5], dPointLoad2[2] = dPointLoad[6];
			dPointLoad2[3] = dPointLoad[7], dPointLoad2[4] = dPointLoad[8]; // P5~P9
			dPointDistance2[0] = dPointDistance[4], dPointDistance2[1] = dPointDistance[5]; // D5~D8
			dPointDistance2[2] = dPointDistance[6], dPointDistance2[3] = dPointDistance[7];
			nIndex = 1;
		}
		else
		{
			ASSERT(0);
			// 있을 수 없는 일이지만 이전 버전에서 [주의] 처리되었으므로 FD, BD는 nIndex==8과 같이 하고
			// 나머지는 main vehicle에 그대로 둔다.
			dFD = dPointDistance[1], dBD = dPointDistance[3];
			nIndex = D_MVHL_NUMLOAD;
		}
		for(int i=nIndex; i<D_MVHL_NUMLOAD; i++)
		{
			if(i>nIndex) dPointLoad[i] = 0.0;
			dPointDistance[i] = 0.0;
		}
	}
	BOOL IsPermitLoad()
	{
		if(!bStandard && nStandardCode == 9 && nLoadType == 2)return TRUE;
		return FALSE;
	}
