struct T_MVLD_BASE
{
	int    nVehicleType;        // 1:Vehicle Class 2:Vehicle
	UINT   VehicleKey;          // T_MVHC_K:nVehicleType=1, T_MVHL_K:nVehicleType=2
	double dVehicleScaleFactor;
	int nMinLoadedLanes;
	int nMaxLoadedLanes;
	T_LLAN_K nSelectedLanes_Old[10]; // 사용 안함
	CArray<T_LLAN_K, T_LLAN_K> aSelectedLanes;

	T_MVLD_BASE() {}
	T_MVLD_BASE(const T_MVLD_BASE& src) { *this = src; }
	T_MVLD_BASE& operator=(const T_MVLD_BASE& src)
	{
		nVehicleType = src.nVehicleType;
		VehicleKey = src.VehicleKey;
		dVehicleScaleFactor = src.dVehicleScaleFactor;
		nMinLoadedLanes = src.nMinLoadedLanes;
		nMaxLoadedLanes = src.nMaxLoadedLanes;
		for(int i=0; i<10; i++) nSelectedLanes_Old[i] = src.nSelectedLanes_Old[i];
		aSelectedLanes.Copy(src.aSelectedLanes);
		
		return *this;
	}

	void Initialize()
	{
		nVehicleType = 1;
		VehicleKey = 0;
		dVehicleScaleFactor = 0.;
		nMinLoadedLanes = 0;
		nMaxLoadedLanes = 1;
		for(int i=0; i<10; i++) nSelectedLanes_Old[i] = 0;
		aSelectedLanes.RemoveAll();
	}
	void Convert791(T_MVLD_BASE_791& rData)
	{
		nVehicleType = rData.nVehicleType;
		VehicleKey = rData.VehicleKey;
		dVehicleScaleFactor = rData.dVehicleScaleFactor;
		nMinLoadedLanes = rData.nMinLoadedLanes;
		nMaxLoadedLanes = rData.nMaxLoadedLanes;
		memcpy(nSelectedLanes_Old, rData.nSelectedLanes_Old, sizeof(nSelectedLanes_Old));
		aSelectedLanes.RemoveAll();
	}
	void Convert510(T_MVLD_BASE_510& rData)
	{
		nVehicleType = 1;
		VehicleKey = rData.KeyVehicleClass;
		dVehicleScaleFactor = rData.dVehicleScaleFactor;
		nMinLoadedLanes = rData.nMinLoadedLanes;
		nMaxLoadedLanes = rData.nMaxLoadedLanes;
		memcpy(nSelectedLanes_Old, rData.nSelectedLanes_Old, sizeof(nSelectedLanes_Old));
		aSelectedLanes.RemoveAll();
	}
};

