		SubLoadCase.nMinLoadedLanes = rData.SubLoadCase.nMinLoadedLanes;
		SubLoadCase.nMaxLoadedLanes = rData.SubLoadCase.nMaxLoadedLanes;
		for (int i = 0; i < 10; i++) SubLoadCase.nSelectedLanes_Old[i] = rData.SubLoadCase.nSelectedLanes_Old[i];
		SubLoadCase.nCountSelectedLanes = rData.SubLoadCase.nCountSelectedLanes;
		for (int i = 0; i < 10; ++i)nSelectedRemainingArea_Old[i] = rData.nSelectedRemainingArea_Old[i];
		nCountSelectedRemainingArea = rData.nCountSelectedRemainingArea;
		bLeading = rData.bLeading;
		nLaneFactorType = rData.nLaneFactorType;
		d2LaneFactor1 = rData.d2LaneFactor1;
		d2LaneFactor2 = rData.d2LaneFactor2;
		d3LaneFactor1 = rData.d3LaneFactor1;
		d3LaneFactor2 = rData.d3LaneFactor2;
		d3LaneFactor3 = rData.d3LaneFactor3;
		d3LaneFactor4 = rData.d3LaneFactor4;
		VehicleSpecial = rData.VehicleSpecial;
		for (int i = 0; i < 10; i++)
		{
			for (int j = 0; j < 2; j++) nStraddLanes_Old[i][j] = rData.nStraddLanes_Old[i][j];
		}
		nCountStraddLanes = rData.nCountStraddLanes;
		bPsi1Factor = rData.bPsi1Factor;
		dMultipleFactor1 = rData.dMultipleFactor1;
		dMultipleFactor2 = rData.dMultipleFactor2;
		dMultipleFactor3 = rData.dMultipleFactor3;
		FootwayK = rData.FootwayK;
		nCountFootwayLanes = rData.nCountFootwayLanes;
		nLoadCombType = rData.nLoadCombType;
		bAutoOptimize = rData.bAutoOptimize;
		dMinVehlDist = rData.dMinVehlDist;
		OptimizeLane = rData.OptimizeLane;
		nMinNumVehicle = rData.nMinNumVehicle;
		nMaxNumVehicle = rData.nMaxNumVehicle;
		nCountOptimize = rData.nCountOptimize;
		OptimizeLane2 = rData.OptimizeLane2;
