	BOOL bConcurrentLink; // Concurrent Force of Elastic/General Link
	BOOL bLink;
	int nLinkFilter;  // 0=All 1=Group;
	T_BNGR_K LinkGrup;
	
	BOOL bPatchLoad;  // (955) PatchLoad (임시)

	void Initialize()
	{
		nCalculationMethod=1;
		nCalcPositionFrame=2;
		nCalcPositionPlate=2;

		bStressCalcFrame = TRUE;

		if(CProduct::IsMovingType(D_PRODUCT_MOVING_US) || CProduct::IsMovingType(D_PRODUCT_MOVING_RUS))
		{
			nLoadPointSelection=1;			
		}
		else
		{
			nLoadPointSelection=2;
		}

		nNumUnitLoad=3;
		bReaction=TRUE;
		nReacFilter=0;
		ReacGrup=0;
		bDisplacement=TRUE;
		nDispFilter=0;
		DispGrup=0;
		bForce=TRUE;
		nForcFilter=0;
		ForcGrup=0;
		bStressCalc = TRUE;
		nInflGenPoint = 0;
		dDistance = 0.0;  // 대화상자에서 초기화
		nMatType = 1;
		nBridgeType = 0;
		nMaxSuccessiveVehicle = 10;
		nIncrementVehicle = 1;
		dMaxSpacingTrain = 10.;
		nMatType_AK = 1;
		nBridgeType_AK = 0;	
		dMinFactors2 = 0.8;
		if(CProduct::IsMovingType(D_PRODUCT_MOVING_RUS))
		{
			bConcurrentCalc = FALSE;
			bConcurrentLink = FALSE;
		}
		else
		{
			bConcurrentCalc = TRUE;
			bConcurrentLink = TRUE;
		}
		bLink = TRUE;
		nLinkFilter = 0;
		LinkGrup = 0;
		bPatchLoad = FALSE;
	}
