{
	CString LineLaneName;
	T_LLANfr_DT arLaneData;
	unsigned int LineLaneId;
	int nLoadDistribution;    // 1:Lane Element, 2:Cross Beam
	T_GRUP_K  ElemGroup;      // if nLoadDistribution=2
	double    dSkewStart;
	double    dSkewEnd;
	int       nMovingDir;     // 0:Forward, 1:Backward, 2:Both
	
	double    dLineWidth;     // Loadable Width
	int       nLineNum;       // Num of Lane
	int       nLineType;      // 0:System load(A/B) 1:Military / Sidewalk
	BOOL      bCentForce;
	BOOL      bUseFactor;

	void Initialize()
	{
		LineLaneName.Empty();
		arLaneData.RemoveAll();
		LineLaneId = 0;
		nLoadDistribution = 1;
		ElemGroup  = 0;
		dSkewStart = 0.0;
		dSkewEnd   = 0.0;
		nMovingDir = 2;

		dLineWidth = 0.0;
		nLineNum   = 1;
		nLineType  = 0;
		bCentForce = TRUE;
		bUseFactor = TRUE;
	}
	T_LLANfr_D() { Initialize(); }
	T_LLANfr_D(const T_LLANfr_D& src) { *this = src; }
	T_LLANfr_D& operator=(const T_LLANfr_D& src)
	{
		LineLaneName = src.LineLaneName;
		arLaneData.Copy(src.arLaneData);
		LineLaneId = src.LineLaneId;
		nLoadDistribution = src.nLoadDistribution;
		ElemGroup = src.ElemGroup;
		dSkewStart = src.dSkewStart;
		dSkewEnd = src.dSkewEnd;
		nMovingDir = src.nMovingDir;

		dLineWidth = src.dLineWidth;
		nLineNum   = src.nLineNum;
		nLineType  = src.nLineType;
		bCentForce = src.bCentForce;
		bUseFactor = src.bUseFactor;
		return *this;
	}
};

