struct T_MVLDbs_BASE
{
	double dScaleFactor;      
	UINT   VehicleKey;  
	T_LLAN_K nSelectedLanes_Old[10]; // 사용 안함
	CArray<T_LLAN_K, T_LLAN_K> aSelectedLanes;
	T_LLAN_K nTwoLanes_Old[45][2];   // 사용 안함
	CArray<T_MVLD_TWO_LANE, T_MVLD_TWO_LANE&> aTwoLanes;
	int    nNumLoadedLanes; // 7.1.0부터 T_MVLDbs_D에 있는 것 이동

	T_MVLDbs_BASE() {}
	T_MVLDbs_BASE(const T_MVLDbs_BASE& src) { *this = src; }
	T_MVLDbs_BASE& operator=(const T_MVLDbs_BASE& src)
	{
		dScaleFactor = src.dScaleFactor;
		VehicleKey = src.VehicleKey;
		for(int i=0; i<10; i++) nSelectedLanes_Old[i] = src.nSelectedLanes_Old[i];
		aSelectedLanes.Copy(src.aSelectedLanes);
		for(int i = 0; i<45; i++)
		{
			for(int j=0; j<2; j++) nTwoLanes_Old[i][j] = src.nTwoLanes_Old[i][j];
		}
		aTwoLanes.Copy(src.aTwoLanes);
		nNumLoadedLanes = src.nNumLoadedLanes;
		
		return *this;
	}

	void Initialize()
	{
		dScaleFactor = 0.;
		VehicleKey = 0;
		for(int i=0; i<10; i++) nSelectedLanes_Old[i] = 0;
		aSelectedLanes.RemoveAll();
		for(int i = 0; i<45; i++)
		{
			for(int j=0; j<2; j++) nTwoLanes_Old[i][j] = 0;
		}
		aTwoLanes.RemoveAll();
		nNumLoadedLanes = 2;
	}
	void Convert791(T_MVLDbs_BASE_791& rData)
	{
		dScaleFactor=rData.dScaleFactor;
		VehicleKey = rData.VehicleKey;    
		memcpy(nSelectedLanes_Old, rData.nSelectedLanes_Old, sizeof(nSelectedLanes_Old));
		aSelectedLanes.RemoveAll();
		memcpy(nTwoLanes_Old, rData.nTwoLanes_Old, sizeof(nTwoLanes_Old));
		aTwoLanes.RemoveAll();
		nNumLoadedLanes = rData.nNumLoadedLanes;
	}
	void Convert702(int nNumLoadedLanesAll, T_MVLDbs_BASE_702& rData)
	{
		dScaleFactor=rData.dScaleFactor;            
		VehicleKey = rData.VehicleKey;    
		memcpy(nSelectedLanes_Old, rData.nSelectedLanes_Old, sizeof(nSelectedLanes_Old));
		aSelectedLanes.RemoveAll();
		memcpy(nTwoLanes_Old, rData.nTwoLanes_Old, sizeof(nTwoLanes_Old));
		aTwoLanes.RemoveAll();
		nNumLoadedLanes = nNumLoadedLanesAll;
	}
};

struct T_MVLDbs_BASE_RW
{
	double dScaleFactor;      
	UINT   VehicleKey;  
	T_LLAN_K nSelectedLanes_Old[10]; // 사용 안함
	int nCountSelectedLanes;
	T_LLAN_K nTwoLanes_Old[45][2];   // 사용 안함
	int nCountTwoLanes;
	int nNumLoadedLanes; // 7.1.0부터 T_MVLDbs_D에 있는 것 이동
	
	void GetMvldbsBase(T_MVLDbs_BASE& rData)
	{
		rData.dScaleFactor = dScaleFactor;
		rData.VehicleKey = VehicleKey;
		for(int i=0; i<10; i++) rData.nSelectedLanes_Old[i] = nSelectedLanes_Old[i];
	  rData.aSelectedLanes.SetSize(nCountSelectedLanes);
		for(int i = 0; i<45; i++)
		{
			for(int j=0; j<2; j++) rData.nTwoLanes_Old[i][j] = nTwoLanes_Old[i][j];
		}
		rData.aTwoLanes.SetSize(nCountTwoLanes);
		rData.nNumLoadedLanes = nNumLoadedLanes;
	}
	void SetMvldbsBase(const T_MVLDbs_BASE& rData)
	{
		dScaleFactor = rData.dScaleFactor;
		VehicleKey = rData.VehicleKey;
		for(int i=0; i<10; i++) nSelectedLanes_Old[i] = rData.nSelectedLanes_Old[i];
		nCountSelectedLanes = (int)rData.aSelectedLanes.GetSize();
		for(int i = 0; i<45; i++)
		{
			for(int j=0; j<2; j++) nTwoLanes_Old[i][j] = rData.nTwoLanes_Old[i][j];
		}
		nCountTwoLanes = (int)rData.aTwoLanes.GetSize();
		nNumLoadedLanes = rData.nNumLoadedLanes;
	}
};

