#define T_MVLDbs_DT CArray<T_MVLDbs_BASE, T_MVLDbs_BASE&>
#define T_MVLDbs_K unsigned int
struct T_MVLDbs_D
{
	CString LoadCaseName;
	CString Description;
	int    nDgnCombFactorType;    // 0= Ultimate Limit State, 1= Serviceability Limit State
	int    nCombinationMethod;    // 0=Combination 1, 1=Combination 2 or 3
	T_LLAN_K    RefLaneK;          // Permit Vehicle 에서 사용
	T_MVLDbs_DT arSubLoadData;
	unsigned int LoadCaseId;
	BOOL   bAutoLiveLoadComb;     // 7.1.0부터 추가됨
	int    nLoadingEffect;        // 0=Combined, 1=Independent
	int    nLoadModel;            // 0=Standard Load(BD 37/01, BS 5400), 1=Special Load(BD 86/11),  2=ALL Model1  3=ALL Model2
	T_MVLDbs_VEHL Vehicle;
	T_MVHL_K VehiSpecialK;
	CArray<T_LLAN_K, T_LLAN_K> aSelectedLanes;
	CArray<T_MVLD_TWO_LANE, T_MVLD_TWO_LANE&> aTwoLanes;
	BOOL bAutoOptimize;
	double dMinVehlDist;
	T_LLANop_K OptimizeLane;
	T_LLANop_K OptimizeLane2;
	int nNumLoadedLanes;
	CArray<T_MVLD_OPTIMIZE, T_MVLD_OPTIMIZE&> aOptimize;	
	CArray<T_LLAN_K, T_LLAN_K> aSelectedRemainingArea;  
	BOOL bOptimRemainArea;  // 896 부터 사용안함. ㅠ

	double dRailTrackFactor[2];
	
	T_MVLDbs_D() { }
	T_MVLDbs_D(T_MVLDbs_D& src) { *this = src; }
	T_MVLDbs_D& operator=(T_MVLDbs_D& src)
	{
		LoadCaseName=src.LoadCaseName;
		Description=src.Description;
		nDgnCombFactorType = src.nDgnCombFactorType;
		nCombinationMethod = src.nCombinationMethod;
		RefLaneK=src.RefLaneK;    
		arSubLoadData.Copy(src.arSubLoadData);
		LoadCaseId=src.LoadCaseId;
		bAutoLiveLoadComb = src.bAutoLiveLoadComb;
		nLoadingEffect = src.nLoadingEffect;
		nLoadModel = src.nLoadModel;
		Vehicle = src.Vehicle;
		VehiSpecialK = src.VehiSpecialK;
		aSelectedLanes.Copy(src.aSelectedLanes);
		aTwoLanes.Copy(src.aTwoLanes);
		bAutoOptimize = src.bAutoOptimize;
		dMinVehlDist = src.dMinVehlDist;
		OptimizeLane = src.OptimizeLane;
		OptimizeLane2 = src.OptimizeLane2;
		nNumLoadedLanes = src.nNumLoadedLanes;
		aOptimize.Copy(src.aOptimize);		
		aSelectedRemainingArea.Copy(src.aSelectedRemainingArea);
		bOptimRemainArea = src.bOptimRemainArea;

		dRailTrackFactor[0] = src.dRailTrackFactor[0];
		dRailTrackFactor[1] = src.dRailTrackFactor[1];

		return *this;
	}

	void Initialize()
	{
		LoadCaseName.Empty();
		Description.Empty();
		nDgnCombFactorType = 0;
		nCombinationMethod = 0;
		RefLaneK = 0;
		arSubLoadData.RemoveAll();
		LoadCaseId=0;
		bAutoLiveLoadComb = TRUE;
		nLoadingEffect = 1;
		nLoadModel = 0;
		Vehicle.Initialize();
		VehiSpecialK = 0;
		aSelectedLanes.RemoveAll();
		aTwoLanes.RemoveAll();
		bAutoOptimize = FALSE;
		dMinVehlDist = 0.0;
		OptimizeLane = 0;
		OptimizeLane2 = 0;
		nNumLoadedLanes = 0;
		aOptimize.RemoveAll();		
		aSelectedRemainingArea.RemoveAll();
		bOptimRemainArea = FALSE;

		dRailTrackFactor[0] = 1.0;
		dRailTrackFactor[1] = 0.75;
	}
};
