struct T_LLANjp_D
{
	CString LineLaneName;
	T_LLANjp_DT arLaneData;
	unsigned int LineLaneId;
	int nLoadDistribution;    // 1:Lane Element, 2:Cross Beam
	T_GRUP_K  ElemGroup;      // if nLoadDistribution=2
	double    dSkewStart;
	double    dSkewEnd;
	int       nMovingDir;     // 0:Forward, 1:Backward, 2:Both
	double    dLineWidth;     // 
	double    dWheelSpace;    // 사용안함.
	BOOL      bCentForce;     // 
	BOOL      bIncludeIF;     // 

	void Initialize()
	{
		LineLaneName.Empty();
		arLaneData.RemoveAll();
		LineLaneId = 0;
		nLoadDistribution = 1;
		ElemGroup = 0;
		dSkewStart = 0.0;
		dSkewEnd = 0.0;
		nMovingDir = 2;
		dLineWidth = 3.0;
		dWheelSpace = 0.0;  // 대화상자에서 국가별로 초기화
		bCentForce = FALSE;
		bIncludeIF = FALSE;
	}
	T_LLANjp_D()
	{
	}
	T_LLANjp_D(T_LLANjp_D& src)
	{
		*this = src;
	}
	T_LLANjp_D& operator=(T_LLANjp_D& src)
	{
		LineLaneName = src.LineLaneName;
		arLaneData.Copy(src.arLaneData);
		LineLaneId = src.LineLaneId;
		nLoadDistribution = src.nLoadDistribution;
		ElemGroup = src.ElemGroup;
		dSkewStart = src.dSkewStart;
		dSkewEnd = src.dSkewEnd;
		nMovingDir = src.nMovingDir;
		dLineWidth = src.dLineWidth;
		dWheelSpace = src.dWheelSpace;
		bCentForce = src.bCentForce;
		bIncludeIF = src.bIncludeIF;
		return *this;
	}
};
