struct T_MVLDch_D
{
	CString LoadCaseName;
	CString Description;
	double  dScaleFactorMuni[8];  // 도시교량 scale factor
	double  dScaleFactorGenL[8];  // 일반하중 scale factor
	int     nCombOption;          // 0:Combined, 1:Independent
	T_MVLDch_DT arSubLoadData;
	unsigned int LoadCaseId;
	int     nBridgeType;     
	double  dScalefactorJTG14[8];  // JTG B01-2014 Scale Factor
	BOOL bAutoOptimize;
	double dMinVehlDist;
	T_LLANop_K OptimizeLane;
	int nMinNumVehicle;
	int nMaxNumVehicle;
	CArray<T_MVLD_OPTIMIZE, T_MVLD_OPTIMIZE&> aOptimize;

	T_MVLDch_D() { }
	T_MVLDch_D(T_MVLDch_D& src) { *this = src; }
	T_MVLDch_D& operator=(T_MVLDch_D& src)
	{
		LoadCaseName = src.LoadCaseName;
		Description = src.Description;
		for(int i=0; i<8; i++)
		{
			dScaleFactorMuni[i] = src.dScaleFactorMuni[i];
			dScaleFactorGenL[i] = src.dScaleFactorGenL[i];
		}
		nCombOption = src.nCombOption;
		arSubLoadData.Copy(src.arSubLoadData);
		LoadCaseId = src.LoadCaseId;
		nBridgeType = src.nBridgeType;
		for(int i=0; i<8; i++) dScalefactorJTG14[i] = src.dScalefactorJTG14[i];
		bAutoOptimize = src.bAutoOptimize;;
		dMinVehlDist = src.dMinVehlDist;;
		OptimizeLane = src.OptimizeLane;;
		nMinNumVehicle = src.nMinNumVehicle;;
		nMaxNumVehicle = src.nMaxNumVehicle;;
		aOptimize.Copy(src.aOptimize);

		return *this;
	}

	void Initialize()
	{
		LoadCaseName.Empty();
		Description.Empty();
		for(int i=0; i<8; i++) 
		{
			dScaleFactorMuni[i] = 0.;
			dScaleFactorGenL[i] = 0.;
		}
		nCombOption = 1;  // Independent를 Default로 한다.
		arSubLoadData.RemoveAll();
		LoadCaseId = 0;
		nBridgeType = 2;
		for(int i=0; i<8; i++) dScalefactorJTG14[i] = 0.0;
		bAutoOptimize = FALSE;
		dMinVehlDist = 0.0;
		OptimizeLane = 0;
		nMinNumVehicle = 0;
		nMaxNumVehicle = 2;
		aOptimize.RemoveAll();
	}
};

