// traffic line lane for transverse moving load
#define T_LLANtr_K unsigned int
struct T_LLANtr_BASE
{
	T_ELEM_K ElemK;
	double   dFactor;
	void Initialize()
	{
		ElemK = 0;
		dFactor = 1.0;
	}
};
#define T_LLANtr_DT CArray<T_LLANtr_BASE, T_LLANtr_BASE&>
struct T_LLANtr_D_712
{
	CString LineLaneName;
	unsigned int LineLaneId;
	CArray<T_ELEM_K, T_ELEM_K> aElemK;
};

struct T_LLANtr_D
{
	CString LineLaneName;
	unsigned int LineLaneId;
	T_LLANtr_DT  aLaneData;
	int nTmp720;

	void Initialize()
	{
		LineLaneName.Empty();
		LineLaneId = 0;
		aLaneData.RemoveAll();
		nTmp720 = 1;
	}
	T_LLANtr_D() {}
	T_LLANtr_D(T_LLANtr_D& src) { *this = src; }
	T_LLANtr_D& operator=(T_LLANtr_D& src)
	{
		LineLaneName = src.LineLaneName;
		LineLaneId   = src.LineLaneId;
		aLaneData.Copy(src.aLaneData);
		nTmp720 = src.nTmp720;
		return *this;
	}
	void Convert712(T_LLANtr_D_712& rData)
	{
		LineLaneName = rData.LineLaneName;
		LineLaneId = rData.LineLaneId;
		int nSize = (int)rData.aElemK.GetSize();
		aLaneData.SetSize(nSize);
		for(int i=0; i<nSize; ++i)
		{
			aLaneData[i].ElemK = rData.aElemK[i];
			aLaneData[i].dFactor = 1.0;
		}
		nTmp720 = 1;
	}
};
struct T_LLANtr_D_CH_712
{
	char LineLaneName[40];
	unsigned int LineLaneId;
	CArray<T_ELEM_K, T_ELEM_K> aElemK;
};
struct T_LLANtr_D_CH
{
	char LineLaneName[40];
	unsigned int LineLaneId;
	T_LLANtr_DT aLaneData;
	int  nTmp720;
	void ConvertToString(T_LLANtr_D& rData)
	{
		ConvertCharStr(LineLaneName, rData.LineLaneName, sizeof(LineLaneName));
		rData.LineLaneId = LineLaneId;
		rData.aLaneData.Copy(aLaneData);
		rData.nTmp720 = 1;
	}
	void ConvertToChar(T_LLANtr_D& rData)
	{
		ConvertStrChar(rData.LineLaneName, LineLaneName, sizeof(LineLaneName));
		LineLaneId = rData.LineLaneId;
		aLaneData.Copy(rData.aLaneData);
		nTmp720 = 1;
	}
	void ConvertTo712(T_LLANtr_D_CH_712 &rData)
	{
		memcpy(LineLaneName, rData.LineLaneName, sizeof(LineLaneName));
		LineLaneId = rData.LineLaneId;
		int nSize = (int)rData.aElemK.GetSize();
		aLaneData.SetSize(nSize);
		for(int i=0; i<nSize; ++i)
		{
			aLaneData[i].ElemK = rData.aElemK[i];
			aLaneData[i].dFactor = 1.0;
		}
		nTmp720 = 1;
	}
};
