struct T_IMPF_D_730
{
	int nLaneType;        // 0: Line Lane, 1: Surface Lane
	int nFactorType;      // 0: Effective Span Length(User Input), 1: Impact Factor, 2: Effective Span Length(Auto)
	double dEffectiveSpanLength;
	double dImpactFactor;
};
struct T_IMPF_D
{
    enum enFactorType {
        effective_span_length_user = 0,
        impact_factor,
        effective_span_length_auto
    };

	int nLaneType;        // 0: Line Lane, 1: Surface Lane
	int nFactorType;      // 0: Effective Span Length(User Input), 1: Impact Factor, 2: Effective Span Length(Auto)
	double dEffectiveSpanLength;
	double dImpactFactor;
	// MNET:2966 20070906 mylee - 여기서부터 740 추가된 변수
	int nElemType;        // 0: Truss, 1: Beam, 2: Plate
	BOOL bParts[5];       // Beam: i 1/4 1/2 3/4 j, Plate: cent i j k l
	BOOL bComponents[8];  // Truss: 앞의 두개만 사용 max min
												// Beam: My_max My_min Mz_max Mz_min Fx_max Fx_min
												// Plate: Mxx_max Mxx_min Myy_max Myy_min Mzz_max Mzz_min Fyy_max Fyy_min

	T_IMPF_D() {}
	T_IMPF_D(const T_IMPF_D& rData) { *this = rData; }
	T_IMPF_D& operator=(const T_IMPF_D& rData)
	{
		nLaneType = rData.nLaneType;
		nFactorType = rData.nFactorType;
		dEffectiveSpanLength = rData.dEffectiveSpanLength;
		dImpactFactor = rData.dImpactFactor;
		nElemType = rData.nElemType;
		for(int i=0 ; i<5 ; ++i) bParts[i] = rData.bParts[i];
		for(int i=0 ; i<8 ; ++i) bComponents[i] = rData.bComponents[i];
		return *this;
	}
	void Initialize()
	{
		nLaneType = 0;
		nFactorType = effective_span_length_user;
		dEffectiveSpanLength = 0.;
		dImpactFactor = 0.;
		nElemType = 0;
		for(int i=0 ; i<5 ; ++i) bParts[i] = FALSE;
		for(int i=0 ; i<8 ; ++i) bComponents[i] = FALSE;
	}
	void Convert730(T_IMPF_D_730& rData)
	{
		nLaneType = rData.nLaneType;
		nFactorType = rData.nFactorType;
		dEffectiveSpanLength = rData.dEffectiveSpanLength;
		dImpactFactor = rData.dImpactFactor;
		nElemType = 0;
		for(int i=0 ; i<5 ; ++i) bParts[i] = FALSE;
		for(int i=0 ; i<8 ; ++i) bComponents[i] = FALSE;
	}
};
